#include <iostream>
#include <vector>
#include <algorithm>
#include <iomanip>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    double T;
    int N;
    if (!(cin >> T >> N)) return 0;

    vector<double> X(N);
    for (int i = 0; i < N; ++i) {
        cin >> X[i];
    }

    sort(X.begin(), X.end());

    double min_dist = (X[0] + X[1]) / 2.0; // vizinhança da primeira cidade

    for (int i = 1; i < N - 1; ++i) {
        double dist = (X[i + 1] - X[i - 1]) / 2.0;
        if (dist < min_dist) {
            min_dist = dist;
        }
    }

    double last_dist = T - (X[N - 2] + X[N - 1]) / 2.0; // vizinhança da última cidade
    if (last_dist < min_dist) {
        min_dist = last_dist;
    }

    cout << fixed << setprecision(2) << min_dist << "\n";

    return 0;
}
